"Айгерим собрал N ракушек, а его сестра — на N больше. Сколько ракушек собрала сестра?": "Aigerim hat N Muscheln gesammelt, und ihre Schwester hat N mehr gesammelt. Wie viele Muscheln hat die Schwester gesammelt?",
"Айша прочитала N страниц, а Данияр — на N страниц меньше. Сколько страниц прочитали они вместе?": "Aischa hat N Seiten gelesen, Daniyar N Seiten weniger. Wie viele Seiten haben sie zusammen gelesen?",
"Айша собрал N ракушек, а его сестра — на N больше. Сколько ракушек собрала сестра?": "Aisha hat N Muscheln gesammelt, und ihre Schwester hat N mehr gesammelt. Wie viele Muscheln hat die Schwester gesammelt?",
