"В году двенадцать месяцев. N умножить на двенадцать будет N.": "Ein Jahr hat zwölf Monate. N mal zwölf ist N.",
"В граммах и килограммах": "In Gramm und Kilogramm",
"В задаче в N действия сразу находят ответ.": "In einer Aufgabe mit N Schritten findet man die Antwort sofort.",
"В задаче с косвенным вопросом нужное число не называется прямо: «на сколько больше», «на сколько меньше», «во сколько раз». Нужно записать краткое условие, выбрать действие и найти ответ. В задачах в N–N действия сначала находим промежуточное число, потом искомое. Например: «В тетради N листов, в блокноте на N больше. Сколько листов в обоих?» — N + N = N в блокноте, N + N = N в обоих. Ответ записываем полным предложением.": "In einer Aufgabe mit indirekter Frage wird die gesuchte Zahl nicht direkt genannt: „um wie viel mehr“, „um wie viel weniger“, „wie viel mal“. Wir müssen die Aufgabe kurz aufschreiben, die Rechenart wählen und die Antwort finden. In Aufgaben mit N–N Schritten finden wir zuerst eine Zwischenzahl, dann die gesuchte. Zum Beispiel: „In einem Heft sind N Blätter, im Notizblock N mehr. Wie viele Blätter sind in beiden?“ — N + N = N im Notizblock, N + N = N in beiden. Die Antwort schreiben wir als ganzen Satz.",
"В зале было N стульев, а в классе — на N меньше. Сколько стульев в классе?": "Im Saal gab es N Stühle, im Klassenzimmer N weniger. Wie viele Stühle gibt es im Klassenzimmer?",
