"В одних сутках двадцать четыре часа. N умножить на двадцать четыре будет N.": "Ein Tag hat vierundzwanzig Stunden. N mal vierundzwanzig ist N.",
"В одной минуте шестьдесят секунд. N умножить на шестьдесят будет N.": "Eine Minute hat sechzig Sekunden. N mal sechzig ist N.",
"В одной тонне тысяча килограммов. Получается N.": "Eine Tonne hat tausend Kilogramm. Das ergibt N.",
"В одном веке N лет.": "Ein Jahrhundert hat N Jahre.",
"В одном веке сто лет.": "Ein Jahrhundert hat hundert Jahre.",
"В одном дециметре десять сантиметров. Умножаем: N умножить на десять будет N.": "Ein Dezimeter hat zehn Zentimeter. Wir multiplizieren: N mal zehn ist N.",
