"В одном метре сто сантиметров. Умножаем: N умножить на сто будет N.": "Ein Meter hat hundert Zentimeter. Wir multiplizieren: N mal hundert ist N.",
"В одном ряду N клеток, а рядов N. Получается N клеток.": "In einer Reihe sind N Kästchen, und es gibt N Reihen. Das ergibt N Kästchen.",
"В одном ряду N мест. Сколько в N рядах?": "In einer Reihe sind N Plätze. Wie viele sind es in N Reihen?",
