"В пакете N конфет. N конфет съели, остальные разложили поровну на N тарелок. Сколько конфет на каждой тарелке?": "In einer Tüte sind N Bonbons. N Bonbons wurden gegessen, der Rest wurde gleichmäßig auf N Teller verteilt. Wie viele Bonbons liegen auf jedem Teller?",
