"В первой коробке N карандаша, во второй на N меньше. Сколько в двух коробках?": "In der ersten Schachtel sind N Stifte, in der zweiten N weniger. Wie viele Stifte sind in beiden Schachteln?",
"В первой коробке N карандашей, а во второй на N больше. Сколько карандашей в двух коробках?": "In der ersten Schachtel sind N Stifte, in der zweiten N mehr. Wie viele Stifte sind in beiden Schachteln?",
"В первый день продали N кг яблок, во второй — на N кг больше. Сколько килограммов яблок продали за два дня?": "Am ersten Tag wurden N kg Äpfel verkauft, am zweiten Tag N kg mehr. Wie viele Kilogramm Äpfel wurden in zwei Tagen verkauft?",
"В рядах: N · N. Ещё N. Всего: N · N + N": "In den Reihen: N · N. Noch N. Insgesamt: N · N + N",
"В ряду N клеток, а рядов N. Всего N · N = N клеток.": "In einer Reihe sind N Kästchen, und es gibt N Reihen. Insgesamt N · N = N Kästchen.",
"В саду N ряда яблонь по N деревьев и N ряда груш по N деревьев. Сколько всего деревьев?": "Im Garten gibt es N Reihen Apfelbäume mit je N Bäumen und N Reihen Birnbäume mit je N Bäumen. Wie viele Bäume sind es insgesamt?",
"В трёх коробках по N шаров и ещё N шаров отдельно. Сколько всего?": "In drei Schachteln sind je N Bälle und noch N Bälle einzeln. Wie viele sind es insgesamt?",
"В уравнении N · x + N = N корень x = N.": "In der Gleichung N · x + N = N ist die Lösung x = N.",
"В уравнении N · x + N = N неизвестное внутри составного выражения. Последнее действие — сложение.": "In der Gleichung N · x + N = N steht die Unbekannte in einem zusammengesetzten Ausdruck. Die letzte Rechenart ist die Addition.",
"В фразе «на N больше» вторая величина = первая + N. Вопрос «на сколько больше» решаем вычитанием.": "In der Wendung „N mehr“ ist die zweite Größe = die erste + N. Die Frage „um wie viel mehr“ löst man durch Subtraktion.",
