"Вспомни таблицу умножения: N · N = N, значит N : N = N": "Erinnere dich an das Einmaleins: N · N = N, also N : N = N",
"Вспомни таблицу: N · N = N, значит, N : N = N": "Erinnere dich an die Tabelle: N · N = N, also N : N = N",
"Выбери самое большое число.": "Wähle die größte Zahl.",
"Выбери самое маленькое число.": "Wähle die kleinste Zahl.",
"Выполнять внетабличное умножение и деление: N · N, N : N, N : N, N : N": "Multipliziere und dividiere außerhalb des Einmaleins: N · N, N : N, N : N, N : N",
"Выразите в граммах: N кг N г": "Gib in Gramm an: N kg N g",
"Выразите в метрах и сантиметрах: N см": "Gib in Metern und Zentimetern an: N cm",
"Выразите в сантиметрах: N м N см": "Gib in Zentimetern an: N m N cm",
"Высказывание": "Aussage",
"Высказывание — предложение, про которое можно сказать: «истинно» или «ложно». Вопрос и просьба высказываниями не являются.": "Eine Aussage ist ein Satz, von dem man sagen kann: „wahr“ oder „falsch“. Eine Frage und eine Bitte sind keine Aussagen.",
"Высказывание?": "Aussage?",
"Вычислять квадрат и куб числа, понимать запись a² и a³": "Das Quadrat und die dritte Potenz einer Zahl berechnen, die Schreibweise a² und a³ verstehen",
"Вычитаем десятки: N дес. − N дес. = N дес. N − N = N": "Wir subtrahieren die Zehner: N Zehner − N Zehner = N Zehner. N − N = N",
"Вычитаемое = уменьшаемое − разность:": "Subtrahend = Minuend − Differenz:",
"Вычитаемое = уменьшаемое − разность: N − N = N": "Subtrahend = Minuend − Differenz: N − N = N",
"Вычти: N м − N см. Ответ в сантиметрах.": "Subtrahiere: N m − N cm. Gib die Antwort in Zentimetern an.",
"Грамм — маленькая единица массы. N кг = N N г. В буханке хлеба примерно N г.": "Ein Gramm ist eine kleine Masseneinheit. N kg = N N g. Ein Laib Brot wiegt etwa N g.",
"Да, получится N": "Ja, das ergibt N",
