"Данияр собрал N ракушек, а его сестра — на N больше. Сколько ракушек собрала сестра?": "Daniyar hat N Muscheln gesammelt, und seine Schwester hat N mehr gesammelt. Wie viele Muscheln hat die Schwester gesammelt?",
"Два и больше": "Zwei und mehr",
"Два нуля (: N)": "Zwei Nullen (: N)",
"Двузначное делимое удобно раскладывать на круглые десятки и табличное число.": "Einen zweistelligen Dividenden zerlegt man am besten in runde Zehner und eine Zahl aus dem Einmaleins.",
"Деление проверяем умножением: частное · делитель = делимое.": "Die Division prüfen wir mit der Multiplikation: Quotient · Teiler = Dividend.",
"Деление проверяют умножением.": "Die Division prüft man mit der Multiplikation.",
"Деление столбиком: находим первое неполное делимое — число, которое можно разделить на делитель. Делим, умножаем, вычитаем, сносим следующую цифру. Например, N : N: первое неполное делимое N, N : N = N; сносим N: N : N — N, пишем N и сносим N: N : N = N. Ответ N. Проверка: N · N = N.": "Schriftliche Division: Wir suchen den ersten unvollständigen Dividenden — eine Zahl, die man durch den Teiler teilen kann. Wir teilen, multiplizieren, subtrahieren und holen die nächste Ziffer herunter. Zum Beispiel N : N: der erste unvollständige Dividend ist N, N : N = N; wir holen N herunter: N : N — N, wir schreiben N und holen N herunter: N : N = N. Antwort: N. Probe: N · N = N.",
"Деление суммы на число. Приёмы деления": "Eine Summe durch eine Zahl teilen. Rechenvorteile beim Teilen",
"Деление — действие, обратное умножению. Если N · N = N, то N : N = N": "Die Division ist die Umkehrung der Multiplikation. Wenn N · N = N, dann N : N = N",
"Деление — обратное действие для умножения. Если N умножить на N будет N, то N разделить на N будет N.": "Die Division ist die Umkehroperation der Multiplikation. Wenn N mal N gleich N ist, dann ist N geteilt durch N gleich N.",
"Делим с остатком: получается N и остаток N. Осталось N.": "Wir teilen mit Rest: das ergibt N und Rest N. N bleiben übrig.",
"Делим с остатком: получается N и остаток N. Полных — N.": "Wir teilen mit Rest: das ergibt N und Rest N. Volle: N.",
"Делим сотни. Получается N.": "Wir teilen die Hunderter. Das ergibt N.",
"Делим, умножаем, вычитаем, сносим следующую цифру — и так по кругу.": "Wir teilen, multiplizieren, subtrahieren, holen die nächste Ziffer herunter — und das immer wieder.",
"Делимое = делитель · неполное частное + остаток:": "Dividend = Teiler · unvollständiger Quotient + Rest:",
"Делимое = частное · делитель: N · N = N": "Dividend = Quotient · Teiler: N · N = N",
"Делитель = делимое : частное: N : N = N": "Teiler = Dividend : Quotient: N : N = N",
"Делитель · неполное частное + остаток = делимое:": "Teiler · unvollständiger Quotient + Rest = Dividend:",
"Делится без остатка?": "Teilbar ohne Rest?",
"Делить многозначные числа на однозначное столбиком": "Mehrstellige Zahlen schriftlich durch eine einstellige Zahl teilen",
"Делить на N нельзя": "Durch N kann man nicht teilen",
"Делить на ноль нельзя, поэтому N : N выполнить невозможно.": "Durch Null kann man nicht teilen, deshalb ist N : N nicht ausführbar.",
"Делить на ноль нельзя.": "Durch Null kann man nicht teilen.",
"Делить сумму на число и применять приёмы деления N : N, N : N, N : N": "Eine Summe durch eine Zahl teilen und die Rechenvorteile N : N, N : N, N : N anwenden",
"Дело началось в N:N и длилось N мин. Во сколько оно закончилось?": "Es begann um N:N und dauerte N min. Wann war es zu Ende?",
"Дерево возможностей показывает, как из первого выбора ветвятся следующие. Так не забываем ни одного варианта.": "Ein Baumdiagramm zeigt, wie sich die nächsten Entscheidungen aus der ersten verzweigen. So vergessen wir keine Möglichkeit.",
"Дерево возможностей помогает не потерять ни один вариант.": "Ein Baumdiagramm hilft, keine Möglichkeit zu übersehen.",
"Дерево возможностей — схема, на которой перебираем все варианты. Если есть N вида блюд и N вида напитков, всего вариантов N · N = N. Высказывание — предложение, про которое можно сказать, истинно оно или ложно: «N > N» — истинно, «N + N = N» — ложно. Подмножество — часть множества: множество {N, N} — подмножество множества {N, N, N, N}.": "Ein Baumdiagramm ist ein Schema, in dem wir alle Möglichkeiten durchgehen. Gibt es N Gerichte und N Getränke, so gibt es insgesamt N · N = N Möglichkeiten. Eine Aussage ist ein Satz, von dem man sagen kann, ob er wahr oder falsch ist: „N > N“ ist wahr, „N + N = N“ ist falsch. Eine Teilmenge ist ein Teil einer Menge: die Menge {N, N} ist eine Teilmenge der Menge {N, N, N, N}.",
"Дерево возможностей. Истинные и ложные высказывания": "Baumdiagramm. Wahre und falsche Aussagen",
