"Десятки: N − N = N.": "Zehner: N − N = N.",
"Десятки: N − N нельзя, занимаем N из старшего разряда: N − N = N.": "Zehner: N − N geht nicht, wir borgen N von der nächsten Stelle: N − N = N.",
"Десятков не хватает: занимаем сотню. N − N = N.": "Es fehlen Zehner: wir borgen einen Hunderter. N − N = N.",
"Десять сотен — это одна тысяча.": "Zehn Hunderter sind ein Tausender.",
"Десять сотен — это одна тысяча: N · N = N.": "Zehn Hunderter sind ein Tausender: N · N = N.",
"Диаметр в N раза больше радиуса: N · N = N": "Der Durchmesser ist N-mal so groß wie der Radius: N · N = N",
