"Длина ленты N см, а другой — в N раз больше. Сколько сантиметров во второй ленте?": "Ein Band ist N cm lang, ein anderes N-mal so lang. Wie viele Zentimeter ist das zweite Band lang?",
"Длина ленты N см, а другой — в N раз короче. Сколько сантиметров во второй ленте?": "Ein Band ist N cm lang, ein anderes N-mal kürzer. Wie viele Zentimeter ist das zweite Band lang?",
"Длина ленты N см, а другой — в N раза больше. Сколько сантиметров во второй ленте?": "Ein Band ist N cm lang, ein anderes N-mal so lang. Wie viele Zentimeter ist das zweite Band lang?",
