"Для N : N раскладываем N = N + N: N : N + N : N = N + N = N.": "Für N : N zerlegen wir N = N + N: N : N + N : N = N + N = N.",
"Для проверки надо подставить корень в уравнение.": "Zur Probe muss man die Lösung in die Gleichung einsetzen.",
"Единиц не хватает: занимаем десяток. N минус N будет N. Десятки: N минус N будет N. Сотни: N минус N будет N. N минус N будет N": "Es fehlen Einer: wir borgen einen Zehner. N minus N ist N. Zehner: N minus N ist N. Hunderter: N minus N ist N. N minus N ist N",
"Единиц не хватает: занимаем десяток. N минус N будет N. Десятков не хватает: занимаем сотню. N минус N будет N. Сотни: N минус N будет N. N минус N будет N": "Es fehlen Einer: wir borgen einen Zehner. N minus N ist N. Es fehlen Zehner: wir borgen einen Hunderter. N minus N ist N. Hunderter: N minus N ist N. N minus N ist N",
"Единиц не хватает: занимаем десяток. N − N = N.": "Es fehlen Einer: wir borgen einen Zehner. N − N = N.",
"Единицы длины: N см = N мм, N дм = N см, N м = N см, N км = N N м. Единицы массы: N кг = N N г, N ц = N кг, N т = N N кг. Чтобы перейти от большей единицы к меньшей, умножаем; от меньшей к большей — делим. Например, N км = N · N N = N N м, N т N кг = N N кг, N N г = N кг.": "Längeneinheiten: N cm = N mm, N dm = N cm, N m = N cm, N km = N N m. Masseneinheiten: N kg = N N g, N q = N kg, N t = N N kg. Von einer größeren Einheit zu einer kleineren multiplizieren wir, von einer kleineren zu einer größeren dividieren wir. Zum Beispiel N km = N · N N = N N m, N t N kg = N N kg, N N g = N kg.",
"Единицы: N + N = N — пишем N, N запоминаем.": "Einer: N + N = N — wir schreiben N, merken N.",
"Единицы: N + N = N, пишем N, N десяток запоминаем.": "Einer: N + N = N, wir schreiben N, merken N Zehner.",
"Единицы: N + N = N.": "Einer: N + N = N.",
"Единицы: N + N = N. Меняется только последняя цифра: N.": "Einer: N + N = N. Es ändert sich nur die letzte Ziffer: N.",
"Единицы: N меньше N, занимаем N из старшего разряда: N − N = N.": "Einer: N ist kleiner als N, wir borgen N von der nächsten Stelle: N − N = N.",
"Единицы: N минус N будет N. Десятков не хватает: занимаем сотню. N минус N будет N. Сотни: N минус N будет N. N минус N будет N": "Einer: N minus N ist N. Es fehlen Zehner: wir borgen einen Hunderter. N minus N ist N. Hunderter: N minus N ist N. N minus N ist N",
"Единицы: N плюс N будет N, пишем N, N десяток запоминаем. Десятки: N плюс N плюс N будет N, пишем N, N сотню запоминаем. Сотни: N плюс N плюс N будет N. N плюс N будет N": "Einer: N plus N ist N, wir schreiben N, merken N Zehner. Zehner: N plus N plus N ist N, wir schreiben N, merken N Hunderter. Hunderter: N plus N plus N ist N. N plus N ist N",
"Единицы: N плюс N будет N, пишем N, N десяток запоминаем. Десятки: N плюс N плюс N будет N. Сотни: N плюс N будет N. N плюс N будет N": "Einer: N plus N ist N, wir schreiben N, merken N Zehner. Zehner: N plus N plus N ist N. Hunderter: N plus N ist N. N plus N ist N",
