"Единицы: N − N = N. Меняется только последняя цифра: N.": "Einer: N − N = N. Es ändert sich nur die letzte Ziffer: N.",
"Ерлан собрал N ракушек, а его сестра — на N больше. Сколько ракушек собрала сестра?": "Yerlan hat N Muscheln gesammelt, und seine Schwester hat N mehr gesammelt. Wie viele Muscheln hat die Schwester gesammelt?",
"Если в разряде получилось больше N, десятки запоминают.": "Ergibt eine Stelle mehr als N, merkt man sich die Zehner.",
"Если все элементы множества A входят в множество B, то A — подмножество B. {N, N} — подмножество {N, N, N, N}.": "Wenn alle Elemente der Menge A in der Menge B liegen, ist A eine Teilmenge von B. {N, N} ist eine Teilmenge von {N, N, N, N}.",
"Если неполное делимое меньше делителя, в частном пишут N.": "Ist der unvollständige Dividend kleiner als der Teiler, schreibt man N in den Quotienten.",
"Если одна часть равна N, а всего частей N, то число: N · N = N": "Wenn ein Teil N ist und es insgesamt N Teile gibt, ist die Zahl: N · N = N",
"Если очередное неполное делимое меньше делителя, в частном пишем ноль.": "Ist der nächste unvollständige Dividend kleiner als der Teiler, schreiben wir eine Null in den Quotienten.",
"Если только + и −, считаем слева направо:": "Gibt es nur + und −, rechnen wir von links nach rechts:",
"Если число оканчивается нулём, при делении на N один ноль убираем: N : N = N.": "Endet eine Zahl auf Null, streichen wir beim Teilen durch N eine Null: N : N = N.",
"Есть N вида хлеба и N вида начинки. Сколько вариантов бутербродов?": "Es gibt N Brotsorten und N Belagsorten. Wie viele Sandwich-Möglichkeiten gibt es?",
"Есть ноль": "Es gibt eine Null",
"Есть ноль в частном?": "Gibt es im Quotienten eine Null?",
"Есть переход через разряд?": "Gibt es einen Übertrag?",
"За N дня прочитали N страниц, по дням поровну. Сколько страниц в день?": "In N Tagen wurden N Seiten gelesen, an jedem Tag gleich viele. Wie viele Seiten pro Tag?",
"За N дня туристы прошли N км, каждый день одинаково. Сколько километров они пройдут за N дней при том же шаге?": "In N Tagen sind die Touristen N km gewandert, jeden Tag gleich viel. Wie viele Kilometer wandern sie in N Tagen im gleichen Tempo?",
"За неделю Бекзат читает по N минут каждый день. Сколько минут он читает за неделю?": "Bekzat liest jeden Tag N Minuten. Wie viele Minuten liest er in einer Woche?",
"За хлеб заплатили N тенге, за молоко — N тенге, за сок — N тенге. Сколько всего заплатили?": "Für Brot wurden N Tenge bezahlt, für Milch N Tenge, für Saft N Tenge. Wie viel wurde insgesamt bezahlt?",
"Забор идёт вокруг грядки, значит, нужен периметр: (N + N) · N = N м": "Der Zaun geht um das Beet herum, also brauchen wir den Umfang: (N + N) · N = N m",
"Забор идёт вокруг грядки, значит, нужно найти периметр. Получается N метров.": "Der Zaun geht um das Beet herum, also müssen wir den Umfang finden. Das ergibt N Meter.",
"Задачи с косвенными вопросами и в N–N действия": "Aufgaben mit indirekten Fragen und mit N–N Schritten",
"Записываем условие кратко, решаем по действиям с пояснениями, проверяем, пишем ответ.": "Wir schreiben die Bedingung kurz auf, lösen schrittweise mit Erklärungen, prüfen und schreiben die Antwort.",
"Здесь подходит единица: килограммами.": "Hier passt die Einheit: Kilogramm.",
