"Здесь подходит единица: сантиметрами.": "Hier passt die Einheit: Zentimeter.",
"Знаменатели одинаковые, значит сравниваем числители: N < N.": "Die Nenner sind gleich, also vergleichen wir die Zähler: N < N.",
"Знаменатели одинаковые, значит сравниваем числители: N = N.": "Die Nenner sind gleich, also vergleichen wir die Zähler: N = N.",
"Знаменатели одинаковые, значит сравниваем числители: N > N.": "Die Nenner sind gleich, also vergleichen wir die Zähler: N > N.",
"Знаменатели одинаковые, значит, больше та дробь, у которой больше числитель: N/N.": "Die Nenner sind gleich, also ist der Bruch mit dem größeren Zähler größer: N/N.",
"Знаменатели одинаковые, значит, сравниваем числители: N больше N. Больше та дробь, у которой числитель больше.": "Die Nenner sind gleich, also vergleichen wir die Zähler: N ist größer als N. Der Bruch mit dem größeren Zähler ist größer.",
"Знаменатели одинаковые, значит, сравниваем числители: N меньше N. Больше та дробь, у которой числитель больше.": "Die Nenner sind gleich, also vergleichen wir die Zähler: N ist kleiner als N. Der Bruch mit dem größeren Zähler ist größer.",
"Знаменатели одинаковые, поэтому больше та дробь, у которой больше числитель.": "Die Nenner sind gleich, deshalb ist der Bruch mit dem größeren Zähler größer.",
"Знаменатели одинаковые, поэтому сравниваем числители. N больше N.": "Die Nenner sind gleich, deshalb vergleichen wir die Zähler. N ist größer als N.",
"Знаменатели одинаковые, поэтому сравниваем числители. N меньше N.": "Die Nenner sind gleich, deshalb vergleichen wir die Zähler. N ist kleiner als N.",
"Идём вправо на N, потом вверх на N — попадаем в точку A.": "Wir gehen N nach rechts, dann N nach oben — wir kommen zu Punkt A.",
"Идём вправо на N, потом вверх на N — попадаем в точку B.": "Wir gehen N nach rechts, dann N nach oben — wir kommen zu Punkt B.",
"Идём вправо на N, потом вверх на N — попадаем в точку C.": "Wir gehen N nach rechts, dann N nach oben — wir kommen zu Punkt C.",
