"Из N · N = N получаем N : N = N и N : N = N": "Aus N · N = N erhalten wir N : N = N und N : N = N",
"Из N вычитаем N. Получается N.": "Von N ziehen wir N ab. Das ergibt N.",
"Из N вычитаем N: N − N = N.": "Von N ziehen wir N ab: N − N = N.",
"Из N вычитаем тех, кто ходит и на шахматы: N − N = N": "Von N ziehen wir die ab, die auch zum Schach gehen: N − N = N",
"Из большего вычитаем меньшее: N минус N будет N.": "Wir ziehen das Kleinere vom Größeren ab: N minus N ist N.",
"Из денег, которые отдали, вычитаем цену. N минус N будет N.": "Vom gegebenen Geld ziehen wir den Preis ab. N minus N ist N.",
"Из крупной в мелкую — умножаем: N км = N · N N = N N м. Из мелкой в крупную — делим: N N г : N N = N кг.": "Von einer großen Einheit zu einer kleinen — multiplizieren wir: N km = N · N N = N N m. Von einer kleinen Einheit zu einer großen — dividieren wir: N N g : N N = N kg.",
"Из крупной единицы в мелкую умножаем.": "Von einer großen Einheit zu einer kleinen multiplizieren wir.",
"Из таблицы на N: N, N, N, N, N, N, N, N, N, N.": "Aus dem Einmaleins mit N: N, N, N, N, N, N, N, N, N, N.",
"Известно, что N · N = N. Сколько будет N : N?": "Es ist bekannt, dass N · N = N. Wie viel ist N : N?",
