"Квадрат (a²)": "Quadrat (a²)",
"Квадрат и куб числа": "Quadrat und dritte Potenz einer Zahl",
"Квадрат или куб?": "Quadrat oder dritte Potenz?",
"Квадрат числа a — это a · a. Записываем a², читаем «а в квадрате».": "Das Quadrat einer Zahl a ist a · a. Wir schreiben a², wir lesen „a Quadrat“.",
"Квадрат числа — произведение двух одинаковых множителей: a² = a · a. Например, N² = N · N = N. Куб числа — произведение трёх одинаковых множителей: a³ = a · a · a. Например, N³ = N · N · N = N. Квадрат связан с площадью квадрата, куб — с объёмом куба: площадь квадрата со стороной N см равна N² = N см².": "Das Quadrat einer Zahl ist das Produkt aus zwei gleichen Faktoren: a² = a · a. Zum Beispiel N² = N · N = N. Die dritte Potenz einer Zahl ist das Produkt aus drei gleichen Faktoren: a³ = a · a · a. Zum Beispiel N³ = N · N · N = N. Das Quadrat hängt mit dem Flächeninhalt eines Quadrats zusammen, die dritte Potenz mit dem Volumen eines Würfels: Der Flächeninhalt eines Quadrats mit der Seite N cm ist N² = N cm².",
"Километр — большая единица длины. N км = N N м. Расстояния между городами измеряют в километрах.": "Ein Kilometer ist eine große Längeneinheit. N km = N N m. Entfernungen zwischen Städten misst man in Kilometern.",
"Кино закончилось в N часов N минут и шло N минут. Когда оно началось?": "Der Film endete um N Uhr N Minuten und dauerte N Minuten. Wann hat er angefangen?",
