"Короткая стрелка показывает часы: N. Длинная показывает минуты: N. Получается N часов N минуты.": "Der kurze Zeiger zeigt die Stunden: N. Der lange Zeiger zeigt die Minuten: N. Das ergibt N Stunden N Minuten.",
