"Короткая стрелка показывает часы: N. Длинная показывает минуты: N. Это N:N.": "Der kurze Zeiger zeigt die Stunden: N. Der lange Zeiger zeigt die Minuten: N. Das ist N:N Uhr.",
"Который час показывают часы?": "Wie spät zeigt die Uhr?",
"Круг разделили на N равных частей. Какое число стоит в дроби внизу, под чертой?": "Ein Kreis wurde in N gleiche Teile geteilt. Welche Zahl steht unten im Bruch, unter dem Strich?",
"Круглое число — число с нулями на конце. N · N: считаем N · N = N и дописываем ноль — получаем N.": "Eine runde Zahl ist eine Zahl mit Nullen am Ende. N · N: Wir rechnen N · N = N und hängen eine Null an — das ergibt N.",
"Куб (a³)": "Dritte Potenz (a³)",
"Куб числа a — это a · a · a. Записываем a³, читаем «а в кубе».": "Die dritte Potenz einer Zahl a ist a · a · a. Wir schreiben a³, wir lesen „a hoch drei“.",
"Купили N тетрадей по N тенге и ручку за N тенге. Какое выражение показывает всю стоимость?": "Es wurden N Hefte zu je N Tenge und ein Stift für N Tenge gekauft. Welcher Ausdruck zeigt die Gesamtkosten?",
"Купили N тетрадей по N тенге и ручку за N тенге. Сколько тенге заплатили?": "Es wurden N Hefte zu je N Tenge und ein Stift für N Tenge gekauft. Wie viele Tenge wurden bezahlt?",
"Купили N тетради по N тг и ручку за N тг. Заплатили N тг. Сдача: N · N = N; N + N = N; N − N = N.": "Es wurden N Hefte zu je N Tg und ein Stift für N Tg gekauft. Bezahlt wurden N Tg. Wechselgeld: N · N = N; N + N = N; N − N = N.",
"Купили N тетради по N тг и ручку за N тг. Сколько всего заплатили?": "Es wurden N Hefte zu je N Tg und ein Stift für N Tg gekauft. Wie viel wurde insgesamt bezahlt?",
"Купили N тетради по N тг и ручку за N тг. Сколько заплатили?": "Es wurden N Hefte zu je N Tg und ein Stift für N Tg gekauft. Wie viel wurde bezahlt?",
"Купили N тетради по N тенге и ручку за N тенге. Сколько тенге заплатили?": "Es wurden N Hefte zu je N Tenge und ein Stift für N Tenge gekauft. Wie viele Tenge wurden bezahlt?",
