"Меняется только последняя цифра. Получается N.": "Es ändert sich nur die letzte Ziffer. Das ergibt N.",
"Миллиметр — очень маленькая единица. N см = N мм. Толщину монеты измеряют в миллиметрах.": "Ein Millimeter ist eine sehr kleine Einheit. N cm = N mm. Die Dicke einer Münze misst man in Millimetern.",
"Множители можно менять местами. Пропущено число N.": "Die Faktoren kann man vertauschen. Die fehlende Zahl ist N.",
