"Найди x: N − x = N": "Finde x: N − x = N",
"Найди x: x + N = N": "Finde x: x + N = N",
"Найди x: x : N = N": "Finde x: x : N = N",
"Найди x: x · N = N": "Finde x: x · N = N",
"Найди x: x − N = N": "Finde x: x − N = N",
"Найди значение выражения: N · N − N · N": "Finde den Wert des Ausdrucks: N · N − N · N",
