"От перестановки множителей произведение не меняется: N · N = N · N = N": "Das Produkt ändert sich nicht, wenn man die Faktoren vertauscht: N · N = N · N = N",
"Ответ N": "Antwort N",
"Ответ в задаче записывают полным предложением.": "Die Antwort auf eine Aufgabe schreibt man als vollständigen Satz.",
"Ответ: N": "Antwort: N",
"Открой тетрадь": "Schlag dein Heft auf",
"Парты в рядах: N умножить на N. Прибавляем те, что у стены. Выражение: N · N + N.": "Bänke in Reihen: N mal N. Dazu addieren wir die an der Wand. Ausdruck: N · N + N.",
"Первая площадь N, вторая N. Сравниваем эти числа.": "Der erste Flächeninhalt ist N, der zweite N. Wir vergleichen diese Zahlen.",
"Первая площадь: N, вторая: N. Значит, N": "Erster Flächeninhalt: N, zweiter: N. Also N",
"Первая площадь: N, вторая: N. Значит, N < N": "Erster Flächeninhalt: N, zweiter: N. Also N < N",
"Первая площадь: N, вторая: N. Значит, N > N": "Erster Flächeninhalt: N, zweiter: N. Also N > N",
"Первое неполное делимое — первая группа цифр, которая не меньше делителя. В N : N это N сотни.": "Der erste unvollständige Dividend ist die erste Zifferngruppe, die nicht kleiner als der Teiler ist. Bei N : N sind das N Hunderter.",
"Первое слагаемое N, второе N. Найди сумму.": "Der erste Summand ist N, der zweite N. Finde die Summe.",
"Первое стоит N, второе стоит N. Второе дороже.": "Das erste kostet N, das zweite kostet N. Das zweite ist teurer.",
"Первое стоит N, второе стоит N. Первое дороже.": "Das erste kostet N, das zweite kostet N. Das erste ist teurer.",
"Первое число пишем сверху, под ним — множитель; разряды выравниваем справа. Начинаем умножение с единиц.": "Wir schreiben die erste Zahl oben, den Faktor darunter; die Stellen richten wir rechts aus. Wir beginnen die Multiplikation mit den Einern.",
"Первое: N · N = N. Второе: N · N = N. Второе дороже.": "Erstes: N · N = N. Zweites: N · N = N. Das zweite ist teurer.",
"Первое: N · N = N. Второе: N · N = N. Первое дороже.": "Erstes: N · N = N. Zweites: N · N = N. Das erste ist teurer.",
