"Переводим в сантиметры: N. Вычитаем N. Получается N.": "Wir rechnen in Zentimeter um: N. Wir ziehen N ab. Das ergibt N.",
"Переводим в сантиметры: N. Прибавляем N. Получается N.": "Wir rechnen in Zentimeter um: N. Wir addieren N. Das ergibt N.",
"Переводим килограммы в граммы: N. Вычитаем N. Получается N.": "Wir rechnen Kilogramm in Gramm um: N. Wir ziehen N ab. Das ergibt N.",
"Переводим метры в сантиметры: N метров это N сантиметров. Теперь сравниваем.": "Wir rechnen Meter in Zentimeter um: N Meter sind N Zentimeter. Jetzt vergleichen wir.",
