"Пересечение множеств — все элементы обоих.": "Der Durchschnitt von Mengen besteht aus den Elementen, die in beiden liegen.",
"Периметр = (длина + ширина) · N: (N + N) · N = N см": "Umfang = (Länge + Breite) · N: (N + N) · N = N cm",
"Периметр прямоугольника N см, одна сторона N см. Найди другую сторону.": "Der Umfang eines Rechtecks ist N cm, eine Seite ist N cm. Finde die andere Seite.",
"Периметр равен длина плюс ширина, всё умножить на два. Получается N сантиметров.": "Der Umfang ist Länge plus Breite, alles mal zwei. Das ergibt N Zentimeter.",
