"Письменное деление столбиком": "Schriftliche Division",
"Письменное умножение на однозначное число": "Schriftliche Multiplikation mit einer einstelligen Zahl",
"Площадь = длина · ширина: N · N = N см²": "Flächeninhalt = Länge · Breite: N · N = N cm²",
"Площадь квадрата со стороной N см равна N см².": "Der Flächeninhalt eines Quadrats mit der Seite N cm ist N cm².",
"Площадь квадрата: сторона · сторона. N · N = N см²": "Flächeninhalt eines Quadrats: Seite · Seite. N · N = N cm²",
"Площадь прямоугольника N квадратных сантиметров, одна сторона N сантиметров. Найди другую сторону.": "Der Flächeninhalt eines Rechtecks ist N Quadratzentimeter, eine Seite ist N Zentimeter. Finde die andere Seite.",
"Площадь прямоугольника N см², длина N см. Найди ширину (в см).": "Der Flächeninhalt eines Rechtecks ist N cm², die Länge ist N cm. Finde die Breite (in cm).",
"Площадь прямоугольника N см², одна сторона N см. Найди другую сторону.": "Der Flächeninhalt eines Rechtecks ist N cm², eine Seite ist N cm. Finde die andere Seite.",
"Площадь прямоугольника: длину умножить на ширину. N · N = N см²": "Flächeninhalt eines Rechtecks: Länge mal Breite. N · N = N cm²",
"Площадь равна длина умножить на ширина. N умножить на N будет N квадратных сантиметров.": "Flächeninhalt ist Länge mal Breite. N mal N ist N Quadratzentimeter.",
"Подбираем: N · N = N, значит N : N = N.": "Wir probieren: N · N = N, also N : N = N.",
