"Подставляем числа. Подходит только то, у которого сумма меньше N. Это N.": "Wir setzen die Zahlen ein. Nur die, deren Summe kleiner als N ist, passt. Das ist N.",
"Подставляем: N · N + N = N + N = N. Равенство верное, значит x = N найден правильно.": "Wir setzen ein: N · N + N = N + N = N. Die Gleichung stimmt, also wurde x = N richtig gefunden.",
"Подходит единица «килограммами».": "Die Einheit „Kilogramm“ passt.",
"Подходит единица «километрами».": "Die Einheit „Kilometer“ passt.",
"Подходит единица «метрами».": "Die Einheit „Meter“ passt.",
"Подходит единица «сантиметрами».": "Die Einheit „Zentimeter“ passt.",
"Покупка стоит N тенге. Ты платишь N тенге. Сколько сдачи?": "Ein Einkauf kostet N Tenge. Du zahlst N Tenge. Wie viel Wechselgeld bekommst du?",
"Покупка стоит N ₸. Заплатили N ₸. Сколько сдачи?": "Ein Einkauf kostet N ₸. Bezahlt wurden N ₸. Wie viel Wechselgeld gibt es?",
"Покупки стоят N + N = N тенге. N больше N, денег не хватит.": "Die Einkäufe kosten N + N = N Tenge. N ist größer als N, das Geld reicht nicht.",
"Покупки стоят N + N = N тенге. N не больше N, денег хватит.": "Die Einkäufe kosten N + N = N Tenge. N ist nicht größer als N, das Geld reicht.",
"Полупериметр: N : N = N. Другая сторона: N − N = N": "Halber Umfang: N : N = N. Die andere Seite: N − N = N",
"Получится N": "Das ergibt N",
"После N идёт N, это тысяча.": "Nach N kommt N, das ist ein Tausend.",
"После N идёт N. Нужно прибавить один.": "Nach N kommt N. Wir müssen eins addieren.",
"После N идёт N: нужно прибавить N.": "Nach N kommt N: Wir müssen N addieren.",
"После девятьсот девяносто девяти идёт тысяча.": "Nach neunhundertneunundneunzig kommt tausend.",
"Поставь знак: N ☐ N": "Setze das Zeichen: N ☐ N",
"Потом x = N : N = N": "Dann ist x = N : N = N",
"Потом возьмём N таких части: N · N = N": "Dann nehmen wir N solche Teile: N · N = N",
"Потом вычитание: N − N = N": "Dann die Subtraktion: N − N = N",
"Потом другая сторона: N − N = N см": "Dann die andere Seite: N − N = N cm",
"Потом сдача: N − N = N тенге": "Dann das Wechselgeld: N − N = N Tenge",
"Потом слева направо: N + N = N, N − N = N": "Dann von links nach rechts: N + N = N, N − N = N",
"Потом сложение: N + N = N": "Dann die Addition: N + N = N",
"Потом умножение: N · N = N": "Dann die Multiplikation: N · N = N",
"При делении на N число не меняется.": "Bei der Division durch N ändert sich die Zahl nicht.",
"При делении на N число не меняется: N : N = N": "Bei der Division durch N ändert sich die Zahl nicht: N : N = N",
"При делении на N число не меняется: N : N = N.": "Bei der Division durch N ändert sich die Zahl nicht: N : N = N.",
"При делении числа на N получилось N и остаток N. Что это за число?": "Als eine Zahl durch N geteilt wurde, kam N heraus und der Rest war N. Welche Zahl war es?",
"При письменном умножении записываем числа столбиком, цифра единиц под цифрой единиц. Сначала умножаем единицы, потом десятки, потом сотни. Если произведение разряда больше N, пишем единицы, а десятки запоминаем и прибавляем к следующему разряду. Например, N · N: N · N = N — пишем N, N запоминаем; N · N = N, плюс N — N. Ответ N.": "Bei der schriftlichen Multiplikation schreiben wir die Zahlen untereinander, Einer unter Einer. Zuerst multiplizieren wir die Einer, dann die Zehner, dann die Hunderter. Ist das Produkt einer Stelle größer als N, schreiben wir die Einer hin und merken die Zehner, die wir zur nächsten Stelle addieren. Zum Beispiel N · N: N · N = N — wir schreiben N, merken N; N · N = N, plus N — N. Antwort: N.",
"При письменном умножении начинают с единиц.": "Bei der schriftlichen Multiplikation beginnen wir mit den Einern.",
"При умножении на N к числу справа приписываем один ноль, при умножении на N — два нуля: N · N = N, N · N = N N. При делении круглого числа на N убираем один ноль, на N — два нуля: N : N = N, N N : N = N. Круглые числа умножаем и делим по табличным случаям: N · N = N, потому что N · N = N, и приписываем ноль.": "Bei der Multiplikation mit N hängen wir rechts eine Null an, bei der Multiplikation mit N zwei Nullen: N · N = N, N · N = N N. Beim Teilen einer runden Zahl durch N streichen wir eine Null, durch N zwei Nullen: N : N = N, N N : N = N. Runde Zahlen multiplizieren und dividieren wir mit den Fällen aus der Tabelle: N · N = N, weil N · N = N ist, und hängen eine Null an.",
"При умножении на N приписываем два нуля: N · N = N N.": "Bei der Multiplikation mit N hängen wir zwei Nullen an: N · N = N N.",
"При умножении на N приписывают два нуля.": "Bei der Multiplikation mit N hängen wir zwei Nullen an.",
"При умножении на N справа приписываем один ноль: N · N = N. Каждая цифра сдвигается на разряд влево.": "Bei der Multiplikation mit N hängen wir rechts eine Null an: N · N = N. Jede Ziffer rückt eine Stelle nach links.",
"Прибавляем десятки: N дес. + N дес. = N дес. N + N = N": "Wir addieren die Zehner: N Zehner + N Zehner = N Zehner. N + N = N",
"Привет! Это Барсик. Сегодня наша тема — «внетабличное умножение и деление». Нажимай на карточки и узнавай новое.": "Hallo! Hier ist Barsik. Heute ist unser Thema „Multiplikation und Division außerhalb des Einmaleins“. Tippe auf die Karten und lerne etwas Neues.",
