"Привет! Это Барсик. Сегодня наша тема — «письменное деление столбиком». Нажимай на карточки и узнавай новое.": "Hallo! Hier ist Barsik. Heute ist unser Thema „Schriftliche Division“. Tippe auf die Karten und lerne etwas Neues.",
"Привет! Это Барсик. Сегодня наша тема — «письменное умножение на однозначное число». Нажимай на карточки и узнавай новое.": "Hallo! Hier ist Barsik. Heute ist unser Thema „Schriftliche Multiplikation mit einer einstelligen Zahl“. Tippe auf die Karten und lerne etwas Neues.",
