"Привет! Это Барсик. Сегодня наша тема — «тонна, грамм, километр, миллиметр». Нажимай на карточки и узнавай новое.": "Hallo! Hier ist Barsik. Heute ist unser Thema „Tonne, Gramm, Kilometer, Millimeter“. Tippe auf die Karten und lerne etwas Neues.",
