"Прикинь ответ: N · N близко к N · N = N. Ответ N подходит.": "Schätze die Antwort: N · N ist nahe bei N · N = N. Die Antwort N passt.",
"Применять распределительное свойство для удобных вычислений": "Das Distributivgesetz für bequemes Rechnen anwenden",
"Приёмы умножения: N · N, N · N, N · N": "Rechenvorteile beim Multiplizieren: N · N, N · N, N · N",
"Проверим делением: N : N = N. Получили первый множитель — решение верное.": "Wir prüfen mit der Division: N : N = N. Wir haben den ersten Faktor erhalten — die Lösung ist richtig.",
"Проверить умножение можно делением: N : N = N. Если получили множитель — всё верно.": "Die Multiplikation kann man durch Division prüfen: N : N = N. Erhält man einen Faktor — ist alles richtig.",
"Проверяем умножением: N · N = N.": "Wir prüfen mit der Multiplikation: N · N = N.",
