"Продолжи счёт: N, N, N, …": "Zähle weiter: N, N, N, …",
"Произведение N · N равно N, а не N.": "Das Produkt N · N ist N, nicht N.",
"Произведение делим на один из множителей, получаем другой множитель.": "Wir teilen das Produkt durch einen der Faktoren und erhalten den anderen Faktor.",
"Произведение не меняется: N · N = N · N = N": "Das Produkt ändert sich nicht: N · N = N · N = N",
"Прямые пересекаются не под прямым углом — просто пересекающиеся.": "Die Geraden schneiden sich nicht im rechten Winkel — sie schneiden sich einfach.",
"Прямые пересекаются под прямым углом — перпендикулярные.": "Die Geraden schneiden sich im rechten Winkel — sie stehen senkrecht aufeinander.",
"Прямые пересекаются под прямым углом. Они перпендикулярные.": "Die Geraden schneiden sich im rechten Winkel. Sie stehen senkrecht aufeinander.",
"Прямые пересекаются, но не под прямым углом. Они просто пересекающиеся.": "Die Geraden schneiden sich, aber nicht im rechten Winkel. Sie schneiden sich einfach.",
"Прямые, которые никогда не пересекаются, называются параллельными.": "Geraden, die sich nie schneiden, heißen parallel.",
"Прямые, которые пересекаются под прямым углом, называются перпендикулярными.": "Geraden, die sich im rechten Winkel schneiden, heißen senkrecht.",
"Радиус в N раза меньше диаметра: N : N = N": "Der Radius ist N-mal kleiner als der Durchmesser: N : N = N",
"Радиус в N раза меньше диаметра: N : N = N см": "Der Radius ist N-mal kleiner als der Durchmesser: N : N = N cm",
"Радиус в два раза меньше диаметра. Получается N сантиметров.": "Der Radius ist die Hälfte des Durchmessers. Das ergibt N Zentimeter.",
"Радиус окружности N см. Чему равен диаметр (в см)?": "Der Radius eines Kreises ist N cm. Wie groß ist der Durchmesser (in cm)?",
"Радиус окружности N см. Чему равен диаметр?": "Der Radius eines Kreises ist N cm. Wie groß ist der Durchmesser?",
"Раздели N на N с остатком. Чему равен остаток?": "Teile N durch N mit Rest. Wie groß ist der Rest?",
"Раздели на удобные части: N и N. N : N = N, N : N = N. N + N = N": "Wir zerlegen in bequeme Teile: N und N. N : N = N, N : N = N. N + N = N",
"Разложим N на N и N. Каждое разделим на N: N и N. Сложим. Получается N.": "Wir zerlegen N in N und N. Wir teilen jeden durch N: N und N. Wir addieren. Das ergibt N.",
"Разложим N на удобные части: N + N.": "Wir zerlegen N in bequeme Teile: N + N.",
"Разложим число N на N и N. Умножим каждое на N и сложим: N плюс N будет N.": "Wir zerlegen die Zahl N in N und N. Wir multiplizieren jede mit N und addieren: N plus N ist N.",
"Разложим: N = N + N.": "Wir zerlegen: N = N + N.",
"Разность плюс вычитаемое должно дать уменьшаемое:": "Differenz plus Subtrahend muss den Minuenden ergeben:",
"Разность — это результат вычитания: N − N = N": "Die Differenz ist das Ergebnis der Subtraktion: N − N = N",
"Раскладываем N = N + N: N : N = N, N : N = N, вместе N. Проверка: N · N = N.": "Wir zerlegen N = N + N: N : N = N, N : N = N, zusammen N. Probe: N · N = N.",
"Раскладываем N = N + N: N · N + N · N = N + N = N.": "Wir zerlegen N = N + N: N · N + N · N = N + N = N.",
"Распределительное свойство умножения": "Distributivgesetz der Multiplikation",
"Распределительное свойство: (a + b) · c = a · c + b · c. Чтобы умножить сумму на число, можно умножить на это число каждое слагаемое и сложить результаты. Например, N · N = (N + N) · N = N · N + N · N = N + N = N. Это свойство помогает умножать двузначные числа в уме: число раскладываем на разрядные слагаемые.": "Das Distributivgesetz: (a + b) · c = a · c + b · c. Um eine Summe mit einer Zahl zu multiplizieren, kann man jeden Summanden mit dieser Zahl multiplizieren und die Ergebnisse addieren. Zum Beispiel N · N = (N + N) · N = N · N + N · N = N + N = N. Dieses Gesetz hilft, zweistellige Zahlen im Kopf zu multiplizieren: wir zerlegen die Zahl in Stellenwert-Summanden.",
"Результат": "Ergebnis",
